arguments.command:
mkdir -p /tmp/stackalloc_test && cd /tmp/stackalloc_test && dotnet new console --force -q && cat << 'EOF' > Program.cs
unsafe
{
    Span<nint> signedSpan = stackalloc nint[4];
    signedSpan[0] = 42;
    signedSpan[1] = -7;
    Console.WriteLine($"Span<nint>: [{signedSpan[0]}, {signedSpan[1]}, {signedSpan[2]}, {signedSpan[3]}]");

    Span<nuint> unsignedSpan = stackalloc nuint[3];
    unsignedSpan[0] = 100;
    Console.WriteLine($"Span<nuint>: [{unsignedSpan[0]}, {unsignedSpan[1]}, {unsignedSpan[2]}]");

    Console.WriteLine($"nint size: {sizeof(nint)} bytes");
    Console.WriteLine($"nuint size: {sizeof(nuint)} bytes");
}
EOF
# Enable unsafe and run
sed -i 's|</PropertyGroup>|<AllowUnsafeBlocks>true</AllowUnsafeBlocks></PropertyGroup>|' stackalloc_test.csproj
dotnet run 2>&1

